import type { Metadata } from 'next'
import { ARIA_NAME } from '@/content/aria'
import { FAB_STORE_URL } from '@/content/fab'
import { getDictionary, type Dictionary } from '@/content/locales'
import { projects } from '@/content/projects'
import { localizedServices } from '@/content/services'
import { site } from '@/content/site'
import { team } from '@/content/team'
import type { Project } from '@/content/types'
import { DEFAULT_LOCALE, LOCALES, localizedPath, OG_LOCALES, type Locale, type Route } from '@/lib/i18n'

/** The share picture generated by app/[lang]/opengraph-image.tsx, in the page's language. */
export function shareImagePath(locale: Locale): string {
  return locale === DEFAULT_LOCALE ? '/opengraph-image' : `/${locale}/opengraph-image`
}

/** A public path as a full address. The home page has no trailing slash. */
export function absoluteUrl(path: string): string {
  return `${site.url}${path === '/' ? '' : path}`
}

/** The full public address of a page in a language. */
export function pageUrl(locale: Locale, route: Route): string {
  return absoluteUrl(localizedPath(locale, route))
}

/** Every page search engines may index, as routes; each exists in every language. */
export function indexableRoutes(): Route[] {
  return [
    { name: 'home' },
    { name: 'aria' },
    ...projects.map((project): Route => ({ name: 'project', slug: project.slug })),
    { name: 'privacy' },
  ]
}

export type LanguageAlternates = Record<Locale | 'x-default', string>

/**
 * hreflang for a page: its address in every language, plus x-default (the
 * Czech one) for visitors whose language we do not have. The map is the same
 * whichever language asks, so the links are reciprocal and include the page itself.
 */
export function languageAlternates(route: Route): LanguageAlternates {
  const byLocale = Object.fromEntries(LOCALES.map((locale) => [locale, pageUrl(locale, route)])) as Record<
    Locale,
    string
  >
  return { ...byLocale, 'x-default': pageUrl(DEFAULT_LOCALE, route) }
}

type PageSeo = { locale: Locale; title: string; description: string; route: Route; image?: string }

/**
 * Metadata for one page: its canonical address in its own language, the same
 * page in the other languages (hreflang) and a large share card. Pages set all
 * of it explicitly, because a page's openGraph replaces the layout's whole
 * openGraph object, image included.
 */
export function pageMetadata({ locale, title, description, route, image }: PageSeo): Metadata {
  const url = pageUrl(locale, route)
  // Without a picture of its own a page shares the site's, described in its language.
  const images = [image ?? { url: shareImagePath(locale), alt: getDictionary(locale).site.shareImage.alt }]
  return {
    title,
    description,
    alternates: { canonical: url, languages: languageAlternates(route) },
    openGraph: {
      type: 'website',
      locale: OG_LOCALES[locale],
      alternateLocale: LOCALES.filter((other) => other !== locale).map((other) => OG_LOCALES[other]),
      siteName: site.name,
      title,
      description,
      url,
      images,
    },
    twitter: { card: 'summary_large_image', title, description, images },
  }
}

// Structured data (schema.org). Every page gets one @graph; nodes point at each
// other by @id, and the ids of the organization and the site never change.

const ORGANIZATION_ID = `${site.url}/#organization`
const WEBSITE_ID = `${site.url}/#website`
const AREA_SERVED = ['CZ', 'SK']
// The site's three languages, and Slovak, which the team speaks with its Slovak clients.
const SPOKEN_LANGUAGES = ['cs', 'sk', 'en', 'de']

export type JsonLdNode = Record<string, unknown> & { '@type': string }
export type JsonLdGraph = { '@context': 'https://schema.org'; '@graph': JsonLdNode[] }

const graph = (...nodes: JsonLdNode[]): JsonLdGraph => ({ '@context': 'https://schema.org', '@graph': nodes })
const ref = (id: string) => ({ '@id': id })

/** Who IndiWeb is: shown in full on the home page. */
export function organizationJsonLd(locale: Locale, dict: Dictionary) {
  return {
    '@type': 'ProfessionalService',
    '@id': ORGANIZATION_ID,
    name: site.name,
    url: site.url,
    email: site.email,
    description: dict.site.description,
    image: absoluteUrl(shareImagePath(locale)),
    founder: team.map((member) => ({ '@type': 'Person', name: member.name })),
    knowsAbout: localizedServices(dict).map((service) => service.title),
    areaServed: AREA_SERVED,
    knowsLanguage: SPOKEN_LANGUAGES,
    sameAs: [FAB_STORE_URL],
  } satisfies JsonLdNode
}

/** IndiWeb in short, for pages that only need to say who is behind them. */
const publisherNode = (): JsonLdNode => ({
  '@type': 'Organization',
  '@id': ORGANIZATION_ID,
  name: site.name,
  url: site.url,
  sameAs: [FAB_STORE_URL],
})

/** The site as a whole, in all its languages. */
export function websiteJsonLd(): JsonLdNode {
  return {
    '@type': 'WebSite',
    '@id': WEBSITE_ID,
    name: site.name,
    url: site.url,
    inLanguage: [...LOCALES],
    publisher: ref(ORGANIZATION_ID),
  }
}

type PageNode = { locale: Locale; route: Route; name: string; description: string }

const breadcrumbId = (locale: Locale, route: Route) => `${pageUrl(locale, route)}#breadcrumb`

function webPageNode({ locale, route, name, description }: PageNode, extra: Record<string, unknown> = {}): JsonLdNode {
  const url = pageUrl(locale, route)
  return {
    '@type': 'WebPage',
    '@id': `${url}#webpage`,
    url,
    name,
    description,
    inLanguage: locale,
    isPartOf: ref(WEBSITE_ID),
    publisher: ref(ORGANIZATION_ID),
    ...extra,
  }
}

/** Home → this page, in the page's language. */
function breadcrumbNode(locale: Locale, route: Route, name: string): JsonLdNode {
  const trail = [
    { name: site.name, url: pageUrl(locale, { name: 'home' }) },
    { name, url: pageUrl(locale, route) },
  ]
  return {
    '@type': 'BreadcrumbList',
    '@id': breadcrumbId(locale, route),
    itemListElement: trail.map((step, index) => ({
      '@type': 'ListItem',
      position: index + 1,
      name: step.name,
      item: step.url,
    })),
  }
}

/** The home page: the studio, the site and the page itself. */
export function homeJsonLd(locale: Locale, dict: Dictionary): JsonLdGraph {
  return graph(
    organizationJsonLd(locale, dict),
    websiteJsonLd(),
    webPageNode(
      { locale, route: { name: 'home' }, name: dict.site.title, description: dict.site.description },
      { about: ref(ORGANIZATION_ID) },
    ),
  )
}

/** Aria's page: a service IndiWeb provides. Says only what the page itself says. */
export function ariaJsonLd(locale: Locale, dict: Dictionary): JsonLdGraph {
  const route: Route = { name: 'aria' }
  const serviceId = `${pageUrl(locale, route)}#service`
  return graph(
    webPageNode(
      { locale, route, name: dict.aria.page.metaTitle, description: dict.aria.page.metaDescription },
      { breadcrumb: ref(breadcrumbId(locale, route)), mainEntity: ref(serviceId) },
    ),
    {
      '@type': 'Service',
      '@id': serviceId,
      name: ARIA_NAME,
      serviceType: dict.aria.page.serviceType,
      description: dict.aria.description,
      url: pageUrl(locale, route),
      provider: ref(ORGANIZATION_ID),
      areaServed: AREA_SERVED,
    },
    breadcrumbNode(locale, route, ARIA_NAME),
    websiteJsonLd(),
    publisherNode(),
  )
}

/** A project's page: the website we built, and where the page sits on ours. */
export function projectJsonLd(locale: Locale, project: Project): JsonLdGraph {
  const route: Route = { name: 'project', slug: project.slug }
  const workId = `${pageUrl(locale, route)}#project`
  return graph(
    webPageNode(
      { locale, route, name: project.title, description: project.summary },
      {
        breadcrumb: ref(breadcrumbId(locale, route)),
        mainEntity: ref(workId),
        primaryImageOfPage: absoluteUrl(project.image),
      },
    ),
    {
      '@type': 'CreativeWork',
      '@id': workId,
      name: project.title,
      description: project.summary,
      url: project.liveUrl,
      image: absoluteUrl(project.image),
      creator: ref(ORGANIZATION_ID),
    },
    breadcrumbNode(locale, route, project.title),
    websiteJsonLd(),
    publisherNode(),
  )
}

/** The privacy notice: a plain page of the site, in its language. */
export function privacyJsonLd(locale: Locale, privacy: { metaTitle: string; metaDescription: string }): JsonLdGraph {
  return graph(
    webPageNode({
      locale,
      route: { name: 'privacy' },
      name: privacy.metaTitle,
      description: privacy.metaDescription,
    }),
    websiteJsonLd(),
    publisherNode(),
  )
}
